const EX=[["Sum of 1..10",`; Sum of 1..10  ->  [2100h] and LEDs\n        ORG  2000h\n        MOV  AX, 0\n        MOV  CX, 10\nAGAIN:  ADD  AX, CX\n        LOOP AGAIN\n        MOV  [2100h], AX\n        OUT  80h, AL\n        INT  3\n`],["Running light",`; Running light on the 8 LEDs (port 80h)\n        ORG  2000h\n        MOV  AL, 1\nSHOW:   OUT  80h, AL\n        MOV  CX, 0FFFFh\nDELAY:  LOOP DELAY\n        ROL  AL, 1\n        JMP  SHOW\n`],["Binary counter (LEDs)",`; Binary counter on the LEDs\n        ORG  2000h\n        MOV  AL, 0\nNEXT:   OUT  80h, AL\n        MOV  CX, 0FFFFh\nWAIT:   LOOP WAIT\n        INC  AL\n        JMP  NEXT\n`],["Traffic light (LEDs)",`; D2 red, D0 green, D1 yellow\n        ORG  2000h\nLIGHT:  MOV  AL, 04h\n        CALL SHOW\n        MOV  AL, 01h\n        CALL SHOW\n        MOV  AL, 02h\n        CALL SHOW\n        JMP  LIGHT\nSHOW:   OUT  80h, AL\n        MOV  CX, 0FFFFh\nWAIT:   LOOP WAIT\n        RET\n`],["Fibonacci -> 2100h",`; First 10 Fibonacci numbers stored from 2100h\n        ORG  2000h\n        MOV  SI, 2100h\n        MOV  CX, 10\n        MOV  AL, 0\n        MOV  BL, 1\nFIB:    MOV  [SI], AL\n        INC  SI\n        MOV  DL, AL\n        ADD  DL, BL\n        MOV  AL, BL\n        MOV  BL, DL\n        LOOP FIB\n        INT  3\n`],["Factorial of 5",`; 5! = 78h -> [2100h] and LEDs\n        ORG  2000h\n        MOV  AX, 1\n        MOV  CX, 5\nFACT:   MUL  CX\n        LOOP FACT\n        MOV  [2100h], AX\n        OUT  80h, AL\n        INT  3\n`],["Largest of 5 bytes",`; Largest of 5 bytes -> [2110h] and LEDs\n        ORG  2000h\n        MOV  SI, OFFSET DATA\n        MOV  CX, 5\n        MOV  AL, 0\nSCAN:   CMP  AL, [SI]\n        JAE  SKIP\n        MOV  AL, [SI]\nSKIP:   INC  SI\n        LOOP SCAN\n        MOV  [2110h], AL\n        OUT  80h, AL\n        INT  3\nDATA:   DB   12h, 45h, 0A7h, 3Ch, 8Eh\n`],["Bubble sort (6 bytes)",`; Sort 6 bytes at 2100h in ascending order\n        ORG  2000h\n        MOV  DL, 5\nOUTER:  MOV  SI, 2100h\n        MOV  CL, DL\n        MOV  CH, 0\nINNER:  MOV  AL, [SI]\n        CMP  AL, [SI+1]\n        JBE  OK\n        XCHG AL, [SI+1]\n        MOV  [SI], AL\nOK:     INC  SI\n        LOOP INNER\n        DEC  DL\n        JNZ  OUTER\n        INT  3\n        ORG  2100h\n        DB   9, 3, 7, 1, 8, 2\n`],["Copy block (REP MOVSB)",`; Copy 8 bytes from 2100h to 2200h\n        ORG  2000h\n        MOV  SI, 2100h\n        MOV  DI, 2200h\n        MOV  CX, 8\n        CLD\n        REP  MOVSB\n        INT  3\n        ORG  2100h\n        DB   11h, 22h, 33h, 44h, 55h, 66h, 77h, 88h\n`],["Matrix: Checkerboard",`; 8x8 LED matrix: checkerboard (row r = port A0h + r)\n        ORG  2000h\n        MOV  DX, 00A0h\n        MOV  CX, 8\n        MOV  AL, 0AAh\nROW:    OUT  DX, AL\n        NOT  AL\n        INC  DX\n        LOOP ROW\n        INT  3\n`],["Matrix: Heart",`; 8x8 LED matrix: draw a heart from a table of 8 bytes\n        ORG  2000h\n        MOV  SI, 2100h\n        MOV  DX, 00A0h\n        MOV  CX, 8\nROW:    MOV  AL, [SI]\n        OUT  DX, AL\n        INC  SI\n        INC  DX\n        LOOP ROW\n        INT  3\n        ORG  2100h\n        DB   66h, 0FFh, 0FFh, 0FFh, 7Eh, 3Ch, 18h, 00h\n`],["Matrix: Beating heart",`; 8x8 LED matrix: a beating heart (two 8-byte frames)\n        ORG  2000h\nBEAT:   MOV  SI, 2100h\n        CALL DRAW\n        CALL WAIT\n        MOV  SI, 2108h\n        CALL DRAW\n        CALL WAIT\n        JMP  BEAT\nDRAW:   MOV  DX, 00A0h\n        MOV  CX, 8\nROW:    MOV  AL, [SI]\n        OUT  DX, AL\n        INC  SI\n        INC  DX\n        LOOP ROW\n        RET\nWAIT:   MOV  BX, 2\nW1:     MOV  CX, 0FFFFh\nW2:     LOOP W2\n        DEC  BX\n        JNZ  W1\n        RET\n        ORG  2100h\n        DB   00h, 00h, 24h, 7Eh, 7Eh, 3Ch, 18h, 00h\n        DB   66h, 0FFh, 0FFh, 0FFh, 7Eh, 3Ch, 18h, 00h\n`],["Matrix: Sweeping pixel",`; 8x8 LED matrix: one pixel sweeps every row, left to right\n        ORG  2000h\nSTART:  MOV  DX, 00A0h\n        MOV  BX, 8\nROW:    MOV  AL, 80h\nCOL:    OUT  DX, AL\n        CALL WAIT\n        SHR  AL, 1\n        JNZ  COL\n        OUT  DX, AL\n        INC  DX\n        DEC  BX\n        JNZ  ROW\n        JMP  START\nWAIT:   MOV  CX, 3000h\nW1:     LOOP W1\n        RET\n`],["80186: OUTSB to LEDs",`; Intel 80186 only: OUTSB sends a table of bytes to the LEDs (port 80h)\n        ORG  2000h\n        MOV  SI, OFFSET TABLE\n        MOV  DX, 0080h\n        MOV  CX, 4\nSEND:   OUTSB\n        PUSH CX\n        MOV  CX, 0FFFFh\nWAIT:   LOOP WAIT\n        POP  CX\n        LOOP SEND\n        INT  3\nTABLE:  DB   81h, 42h, 24h, 18h\n`],["80186: OUTS heart",`; Intel 80186 only: OUTS DX, BYTE PTR [SI] draws a heart on the 8x8 matrix\n        ORG  2000h\n        MOV  SI, OFFSET HEART\n        MOV  DX, 00A0h\n        MOV  CX, 8\nROW:    OUTS DX, BYTE PTR [SI]\n        INC  DX\n        LOOP ROW\n        INT  3\nHEART:  DB   66h, 0FFh, 0FFh, 0FFh, 7Eh, 3Ch, 18h, 00h\n`],["80186: REP INSB",`; Intel 80186 only: REP INSB reads port 80h (the LEDs) 8 times into 2100h\n        ORG  2000h\n        MOV  AL, 5Ah\n        OUT  80h, AL\n        MOV  DI, 2100h\n        MOV  DX, 0080h\n        MOV  CX, 8\n        CLD\n        REP  INSB\n        INT  3\n`],["80186: INS word",`; Intel 80186 only: INS WORD PTR [DI], DX reads ports A0h and A1h as one word\n        ORG  2000h\n        MOV  AL, 18h\n        OUT  0A0h, AL\n        MOV  AL, 3Ch\n        OUT  0A1h, AL\n        MOV  DX, 00A0h\n        MOV  DI, 2100h\n        INS  WORD PTR [DI], DX\n        INT  3\n`]];;
